import { ProfileHeader, type FollowState } from "march/ui"

// bir saksı bitkisinin profili: takip edince takipçi sayısı döner; istatistikler "Yaprak / Hayran / Güneş"
const LEAF = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42mPY/f2C0tE4BrFUE5FgXQAtngULJa1nqAAAAABJRU5ErkJggg=="

export function PlantProfile() {
  let $follow: FollowState = "follow"
  return <ProfileHeader follow={$follow} onFollow={(s) => $follow = s} cover="sm"
    user={{ name: "Fesleğen 🌿", handle: "feslegen.balkon", cover: LEAF, bio: "Balkonda yaşıyorum. Sabah güneşi severim, akşam sulanırım.",
      posts: 42, followers: 318, following: 1, story: "new" }}
    labels={{ posts: "Yaprak", followers: "Hayran", following: "Güneş" }} />
}

import { ProfileHeader, toast, type FollowState } from "march/ui"
import { link, flag } from "march/icons"

// bir kulübün profil sayfasının üstü: takip et (sayaç birlikte değişir), mesaj, istatistik listeleri, hikâyeler ve
// ⋯ menüsünde bağlantıyı kopyala ve bildir
const SEA = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42mOw2PuDb+lLBlm/Gz+LxQAthgZP+C/XcgAAAABJRU5ErkJggg=="
const LISTS = { posts: "Gönderiler", followers: "Takipçiler", following: "Takip edilenler" }

export function ClubProfile() {
  let $follow: FollowState = "follow"
  return <ProfileHeader follow={$follow} onFollow={(s) => { $follow = s; if (s === "following") toast("Kulübü takip ediyorsun") }}
    onMessage={() => toast("Sohbet açılır")} onStat={(w) => toast(`${LISTS[w]} listesi açılır`)} onAvatar={() => toast("Hikâyeler açılır")}
    menu={[{ label: "Bağlantıyı kopyala", icon: link, onSelect: () => toast("Kopyalandı") }, { label: "Bildir", icon: flag, danger: true, onSelect: () => toast("Bildirildi") }]}
    user={{ name: "HADİ Koşu Kulübü", handle: "hadi.kosu", verified: true, story: "new", cover: SEA,
      bio: "Her pazar sabahı sahilde koşuyoruz. Tempo grupları, yeni başlayanlar için yürüyüş ve dönüşte kahve ☕",
      posts: 248, followers: 986, following: 186 }} />
}

import { ProfileHeader, Button, Badge, Card, type FollowState, type ProfileUser } from "march/ui"
import { send, settings, star, badgeCheck } from "march/icons"

// ProfileHeader'ın bütün özellikleri: profil (erişimci), kendi profilim (self), takip durumu ve onFollow, mesaj,
// düzenle, istatistik ve avatar olayları, ⋯ menüsü, kapak boyu, kendi metinler, istatistik seçimi, kendi ikonlar,
// mesaj düğmesi rengi ve sınıf; altta koyu zeminde sade bir ikinci başlık
const DAWN = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42mP4+6zr9yQbhuXdvwz1GgE6ZgdD1tcTigAAAABJRU5ErkJggg=="

export function ProfileHeaderLab() {
  let $self = false
  let $follow: FollowState = "follow"
  let $cover: "sm" | "md" | "lg" | "none" = "md"
  let $log = "-"
  const user = (): ProfileUser => ({ name: "Ece Yıldız", handle: "ece", verified: true, story: "seen", cover: DAWN, private: false,
    bio: "Fotoğraf, bisiklet ve iyi kahve.", posts: 57, followers: 1204, following: 310 })
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button size="sm" variant="ghost" on:click={() => $self = !$self}>{$self ? "Başkasının profili" : "Kendi profilim"}</Button>
      <Button size="sm" variant="ghost" on:click={() => $cover = $cover === "md" ? "lg" : $cover === "lg" ? "none" : "md"}>{`Kapak: ${$cover}`}</Button>
      <Badge tone="primary">{$log}</Badge>
    </div>
    <ProfileHeader class="lab-profile" user={user} self={() => $self} follow={() => $follow} cover={() => $cover}
      onFollow={(s) => { $follow = s; $log = `takip: ${s}` }} onMessage={() => $log = "mesaj"} onEdit={() => $log = "düzenle"}
      onStat={(w) => $log = `liste: ${w}`} onAvatar={() => $log = "hikâyeler"}
      menu={[{ label: "Profili paylaş", icon: star, onSelect: () => $log = "paylaşıldı" }]}
      labels={{ profile: (n) => `${n} profili`, edit: "Profili düzenle", message: "Mesaj at", more: "Daha fazla", verified: "Onaylı",
        posts: "Gönderi", followers: "Takipçi", following: "Takip" }}
      stats={["followers", "posts"]} verifiedIcon={badgeCheck} messageIcon={send} menuIcon={settings} messageColor="brand-blue" />
    <Card m:theme="night">
      <ProfileHeader user={{ name: "Gizli Hesap", private: true }} cover="none" stats={false} verifiedIcon={false} messageIcon={false} onMessage={() => $log = "gizli hesaba mesaj"} />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ProfileHeaderLab } from "./ProfileHeaderLab.tsx"

// ProfileHeaderLab'in testleri: kaydedince Testler sekmesinde çalışır
test("istatistikler seçilen sırada ve kendi adlarıyla; basınca onStat çalışır", async () => {
  const s = renderTest(() => <ProfileHeaderLab />)
  expect(s.sees("Takipçi")).toBe(true)
  expect(s.sees("Takip edilenler")).toBe(false)
  const stat = s.all(".lab-profile button").find((b) => (b.textContent ?? "").includes("Gönderi"))
  expect(stat).toBeTruthy()
  await s.click(stat!)
  expect(s.sees("liste: posts")).toBe(true)
})

test("Mesaj at düğmesi onMessage'ı çalıştırır", async () => {
  const s = renderTest(() => <ProfileHeaderLab />)
  await s.click("Mesaj at")
  expect(s.sees("mesaj")).toBe(true)
})

test("kendi profilimde takip ve mesaj yerine Profili düzenle çıkar", async () => {
  const s = renderTest(() => <ProfileHeaderLab />)
  await s.click("Kendi profilim")
  expect(s.find("Mesaj at")).toBe(null)
  await s.click("Profili düzenle")
  expect(s.sees("düzenle")).toBe(true)
})

test("ikinci başlıkta kapak ve istatistik yok; ilkinde iki istatistik var", () => {
  const s = renderTest(() => <ProfileHeaderLab />)
  const [lab, plain] = s.all(".m-prof")
  expect(lab?.querySelectorAll(".m-prof-stat").length).toBe(2)
  expect(plain?.textContent).toContain("Gizli Hesap")
  expect(plain?.querySelector(".m-prof-stats")).toBe(null)
  expect(plain?.querySelector(".m-prof-cover-art")).toBe(null)
})
